struct Line {
    flags: TokenFlags,
    tokens_start: u32,
    tokens_end: u32,
}

/// Keeps track of whether we are currently visiting a class or function definition in a
/// [`LogicalLine`]. If we are visiting a class or function, the enum also keeps track
/// of the [type parameters] of the class/function.
///
/// Call [`DefinitionState::visit_token_kind`] on the [`TokenKind`] of each
/// successive [`LogicalLineToken`] to ensure the state remains up to date.
///
/// [type parameters]: https://docs.python.org/3/reference/compound_stmts.html#type-params
#[derive(Debug, Clone, Copy)]
enum DefinitionState {
    InClass(TypeParamsState),
    InFunction(TypeParamsState),
    InTypeAlias(TypeParamsState),
    NotInDefinition,
    Start,
    AfterAsync,
}

impl DefinitionState {
    fn from_tokens<'a>(tokens: impl IntoIterator<Item = &'a LogicalLineToken>) -> Self {
        let mut state = Self::Start;
        for token in tokens {
            state.visit_token_kind(token.kind());
            match state {
                Self::Start | Self::AfterAsync => {}
                _ => break,
            }
        }
        match state {
            Self::Start | Self::AfterAsync => Self::NotInDefinition,
            Self::InClass(_)
            | Self::InFunction(_)
            | Self::InTypeAlias(_)
            | Self::NotInDefinition => state,
        }
    }

    const fn in_function_definition(self) -> bool {
        matches!(self, Self::InFunction(_))
    }

    const fn type_params_state(self) -> Option<TypeParamsState> {
        match self {
            Self::InClass(state) | Self::InFunction(state) | Self::InTypeAlias(state) => {
                Some(state)
            }
            Self::NotInDefinition | Self::Start | Self::AfterAsync => None,
        }
    }

    fn in_type_params(self) -> bool {
        matches!(
            self.type_params_state(),
            Some(TypeParamsState::InTypeParams { .. })
        )
    }

    fn visit_token_kind(&mut self, token_kind: TokenKind) {
        if matches!(self, Self::Start | Self::AfterAsync) {
            if matches!(self, Self::Start) {
                if matches!(token_kind, TokenKind::Indent | TokenKind::Dedent) {
                    return;
                }

                if token_kind.is_keyword() {
                    if token_kind == TokenKind::Class {
                        let type_params = TypeParamsState::default();
                        *self = Self::InClass(type_params);
                    } else if token_kind == TokenKind::Def {
                        let type_params = TypeParamsState::default();
                        *self = Self::InFunction(type_params);
                    } else if token_kind == TokenKind::Async {
                        *self = Self::AfterAsync;
                    } else if token_kind == TokenKind::Type {
                        let type_params = TypeParamsState::default();
                        *self = Self::InTypeAlias(type_params);
                    } else {
                        *self = Self::NotInDefinition;
                    }
                } else {
                    *self = Self::NotInDefinition;
                }
            } else if token_kind == TokenKind::Def {
                let type_params = TypeParamsState::default();
                *self = Self::InFunction(type_params);
            } else {
                *self = Self::NotInDefinition;
            }
            return;
        }

        let type_params_state_mut = if let Self::InClass(type_params_state)
        | Self::InFunction(type_params_state)
        | Self::InTypeAlias(type_params_state) = self
        {
            type_params_state
        } else {
            return;
        };

        if is_non_logical_token(token_kind) {
            return;
        }

        let is_opening_paren = token_kind == TokenKind::Lpar;
        let is_opening_square = token_kind == TokenKind::Lsqb;
        let is_closing_square = token_kind == TokenKind::Rsqb;

        if type_params_state_mut.before_type_params() {
            if is_opening_paren {
                let ended = TypeParamsState::TypeParamsEnded;
                *type_params_state_mut = ended;
            } else if is_opening_square {
                let opened = TypeParamsState::InTypeParams {
                    inner_square_brackets: 0,
                };
                *type_params_state_mut = opened;
            }
        } else if let TypeParamsState::InTypeParams {
            inner_square_brackets,
        } = type_params_state_mut
        {
            if is_opening_square {
                let nested = *inner_square_brackets + 1;
                *inner_square_brackets = nested;
            } else if is_closing_square {
                if *inner_square_brackets == 0 {
                    let ended = TypeParamsState::TypeParamsEnded;
                    *type_params_state_mut = ended;
                } else {
                    let remaining = *inner_square_brackets - 1;
                    *inner_square_brackets = remaining;
                }
            }
        } else {
            let ended = TypeParamsState::TypeParamsEnded;
            *type_params_state_mut = ended;
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
enum TypeParamsState {
    #[default]
    BeforeTypeParams,
    InTypeParams {
        inner_square_brackets: u32,
    },
    TypeParamsEnded,
}

impl TypeParamsState {
    const fn before_type_params(self) -> bool {
        matches!(self, Self::BeforeTypeParams)
    }
}

#[cfg(test)]
mod tests {
    use ruff_python_parser::parse_module;

    use crate::Locator;

    use super::LogicalLines;

    #[test]
    fn multi_line() {
        assert_logical_lines(
            r"
x = 1
y = 2
z = x + 1"
                .trim(),
            &["x = 1", "y = 2", "z = x + 1"],
        );
    }

    #[test]
    fn indented() {
        assert_logical_lines(
            r"
x = [
  1,
  2,
  3,
]
y = 2
z = x + 1"
                .trim(),
            &["x = [\n  1,\n  2,\n  3,\n]", "y = 2", "z = x + 1"],
        );
    }

    #[test]
    fn string_assignment() {
        assert_logical_lines("x = 'abc'".trim(), &["x = 'abc'"]);
    }

    #[test]
    fn function_definition() {
        assert_logical_lines(
            r"
def f():
  x = 1
f()"
            .trim(),
            &["def f():", "x = 1", "f()"],
        );
    }

    #[test]
    fn trivia() {
        assert_logical_lines(
            r#"
def f():
  """Docstring goes here."""
  # Comment goes here.
  x = 1
f()"#
                .trim(),
            &[
                "def f():",
                "\"\"\"Docstring goes here.\"\"\"",
                "",
                "x = 1",
                "f()",
            ],
        );
    }

    #[test]
    fn empty_line() {
        assert_logical_lines(
            r"
if False:

    print()
"
            .trim(),
            &["if False:", "print()", ""],
        );
    }

    fn assert_logical_lines(contents: &str, expected: &[&str]) {
        let parsed = parse_module(contents).unwrap();
        let locator = Locator::new(contents);
        let actual: Vec<String> = LogicalLines::from_tokens(parsed.tokens(), &locator)
            .into_iter()
            .map(|line| line.text_trimmed())
            .map(ToString::to_string)
            .collect();
        let expected: Vec<String> = expected.iter().map(ToString::to_string).collect();
        assert_eq!(actual, expected);
    }
}

